-- ---------------------------------------------------------------- 1. schemas and helper functions
CREATE SCHEMA IF NOT EXISTS "identity";
CREATE SCHEMA IF NOT EXISTS "app";
REVOKE ALL ON SCHEMA "identity", "app" FROM PUBLIC;
-- Functions are not executable by PUBLIC unless granted below (PostgreSQL's default is EXECUTE TO PUBLIC).
ALTER DEFAULT PRIVILEGES FOR ROLE migrator REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

-- RFC 9562 UUID v7 (SRS 5.1). PostgreSQL 17 has no built-in; uuidv7() arrives in 18.
-- Takes a v4 UUID, overwrites the first 48 bits with Unix milliseconds and flips the version nibble 4 -> 7.
-- OVERLAY/SUBSTRING use SQL-standard keyword syntax, which cannot be schema-qualified; with search_path ''
-- they still resolve to pg_catalog only.
CREATE FUNCTION app.uuid_generate_v7() RETURNS uuid
LANGUAGE sql VOLATILE PARALLEL SAFE SET search_path = '' AS $$
  SELECT pg_catalog.encode(
    pg_catalog.set_bit(pg_catalog.set_bit(
      overlay(pg_catalog.uuid_send(pg_catalog.gen_random_uuid())
        PLACING substring(pg_catalog.int8send(
          pg_catalog.floor(pg_catalog.date_part('epoch', pg_catalog.clock_timestamp()) * 1000)::bigint) FROM 3)
        FROM 1 FOR 6),
      52, 1), 53, 1),
    'hex')::uuid
$$;

-- Tenant and actor context. NULLIF is mandatory: a pooled connection that once ran a transaction-local
-- set_config reports '' afterwards, and ''::uuid raises 22P02 (Spike B B-1). Missing context => NULL =>
-- no row matches => zero rows (fail closed). Not SECURITY DEFINER and no SET clause, so they stay inlinable.
CREATE FUNCTION app.current_workspace() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  SELECT NULLIF(pg_catalog.current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE FUNCTION app.current_actor_user() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  SELECT NULLIF(pg_catalog.current_setting('app.user_id', true), '')::uuid
$$;

