-- ---------------------------------------------------------------- 3. integrity constraints
-- Lower-case e-mail instead of citext: Supabase has no citext installed and only its operator role may add
-- extensions. Better Auth lower-cases addresses itself; the CHECK makes the unique index case-insensitive.
ALTER TABLE "identity"."users"
  ADD CONSTRAINT "users_email_lowercase" CHECK (email = lower(email) AND char_length(email) BETWEEN 3 AND 320),
  ADD CONSTRAINT "users_name_length" CHECK (char_length(name) <= 256),
  ADD CONSTRAINT "users_locale_format" CHECK (locale ~ '^[a-z]{2}(-[A-Z]{2})?$');

ALTER TABLE "app"."platform_admins"
  ADD CONSTRAINT "platform_admins_reason_length" CHECK (char_length(btrim(reason)) BETWEEN 3 AND 500);

ALTER TABLE "app"."workspaces"
  ADD CONSTRAINT "workspaces_slug_format"
    CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,46}[a-z0-9]$' AND position('--' IN slug) = 0),
  ADD CONSTRAINT "workspaces_name_length" CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
  ADD CONSTRAINT "workspaces_suspension_consistent"
    CHECK ((status = 'suspended') = (suspended_at IS NOT NULL)),
  ADD CONSTRAINT "workspaces_deletion_consistent"
    CHECK ((deleted_at IS NULL) = (scheduled_purge_at IS NULL) AND (deleted_at IS NULL OR scheduled_purge_at > deleted_at));

ALTER TABLE "app"."invitations"
  ADD CONSTRAINT "invitations_email_lowercase" CHECK (email = lower(email) AND char_length(email) BETWEEN 3 AND 320),
  ADD CONSTRAINT "invitations_role_not_owner" CHECK (role <> 'owner'),
  ADD CONSTRAINT "invitations_token_hash_sha256" CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "invitations_expiry_after_creation" CHECK (expires_at > created_at),
  ADD CONSTRAINT "invitations_single_outcome" CHECK (accepted_at IS NULL OR revoked_at IS NULL),
  ADD CONSTRAINT "invitations_acceptance_consistent" CHECK ((accepted_at IS NULL) = (accepted_by IS NULL));
-- At most one open invitation per address and workspace.
CREATE UNIQUE INDEX "invitations_open_per_email" ON "app"."invitations" (workspace_id, email)
  WHERE accepted_at IS NULL AND revoked_at IS NULL;

ALTER TABLE "app"."projects"
  ADD CONSTRAINT "projects_name_length" CHECK (char_length(btrim(name)) BETWEEN 1 AND 120),
  ADD CONSTRAINT "projects_category_length" CHECK (char_length(category) <= 80),
  ADD CONSTRAINT "projects_city_length" CHECK (char_length(city) <= 80);

ALTER TABLE "app"."client_contacts"
  ADD CONSTRAINT "client_contacts_name_length" CHECK (char_length(btrim(name)) BETWEEN 1 AND 120),
  ADD CONSTRAINT "client_contacts_email_lowercase" CHECK (email = lower(email) AND char_length(email) <= 320),
  ADD CONSTRAINT "client_contacts_phone_length" CHECK (char_length(phone) <= 32),
  ADD CONSTRAINT "client_contacts_whatsapp_length" CHECK (char_length(whatsapp) <= 32);

-- RFC 1123 host names, lower-case, no trailing dot (SEC-12: exact-match lookups, no wildcards).
ALTER TABLE "app"."domains"
  ADD CONSTRAINT "domains_hostname_format" CHECK (
    char_length(hostname) <= 253
    AND hostname ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'),
  ADD CONSTRAINT "domains_active_has_timestamp" CHECK (status <> 'active' OR activated_at IS NOT NULL);
-- One live platform subdomain per project (FR-DOM-01).
CREATE UNIQUE INDEX "domains_one_subdomain_per_project" ON "app"."domains" (project_id)
  WHERE type = 'subdomain' AND deleted_at IS NULL;

ALTER TABLE "app"."audit_logs"
  ADD CONSTRAINT "audit_logs_action_format"
    CHECK (char_length(action) <= 100 AND action ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
  ADD CONSTRAINT "audit_logs_metadata_bounded"
    CHECK (jsonb_typeof(metadata) = 'object' AND pg_column_size(metadata) <= 8192),
  ADD CONSTRAINT "audit_logs_field_lengths" CHECK (
    char_length(target_type) <= 64 AND char_length(target_id) <= 128
    AND char_length(correlation_id) <= 128 AND char_length(user_agent) <= 512);

ALTER TABLE "app"."notifications"
  ADD CONSTRAINT "notifications_type_format"
    CHECK (char_length(type) <= 100 AND type ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
  ADD CONSTRAINT "notifications_payload_bounded"
    CHECK (jsonb_typeof(payload) = 'object' AND pg_column_size(payload) <= 8192);

-- ---------------------------------------------------------------- 4. row-level security (SRS 5.3)
-- Every app table: ENABLE + FORCE (FORCE also binds the owner, Spike B result 6). Policies name app_user only;
-- any other role, including migrator, sees and changes nothing unless a policy below names it.
ALTER TABLE "app"."platform_admins" ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."workspaces"      ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."memberships"     ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."invitations"     ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."projects"        ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."client_contacts" ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."domains"         ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."audit_logs"      ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;
ALTER TABLE "app"."notifications"   ENABLE ROW LEVEL SECURITY, FORCE ROW LEVEL SECURITY;

-- Writes require an active, not-deleted workspace (FR-WS-04: suspension blocks dashboard writes).
-- SECURITY DEFINER so it can read the workspace row whatever the caller's policies; `(SELECT ...)` in the
-- policies below makes PostgreSQL evaluate it once per statement, not once per row.
CREATE FUNCTION app.workspace_writable() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM app.workspaces w
     WHERE w.id = app.current_workspace() AND w.status = 'active' AND w.deleted_at IS NULL)
$$;

-- workspaces: the row of the current workspace, plus read-only access to every workspace the actor belongs
-- to (workspace switcher, FR-AUTH-08). Creation sets the context to the new, server-generated id first.
CREATE POLICY tenant_select ON "app"."workspaces" FOR SELECT TO app_user
  USING (id = app.current_workspace());
CREATE POLICY member_select ON "app"."workspaces" FOR SELECT TO app_user
  USING (EXISTS (SELECT 1 FROM app.memberships m
                  WHERE m.workspace_id = workspaces.id AND m.user_id = app.current_actor_user()));
CREATE POLICY tenant_insert ON "app"."workspaces" FOR INSERT TO app_user
  WITH CHECK (id = app.current_workspace() AND status = 'active' AND deleted_at IS NULL);
-- Not gated on deleted_at, so an owner can cancel a scheduled deletion during the grace period.
CREATE POLICY tenant_update ON "app"."workspaces" FOR UPDATE TO app_user
  USING (id = app.current_workspace() AND status = 'active')
  WITH CHECK (id = app.current_workspace() AND status = 'active');

-- memberships: workspace policy plus the Spike F `self_select` bridge (actor reads only their own rows).
CREATE POLICY tenant_select ON "app"."memberships" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace());
CREATE POLICY self_select ON "app"."memberships" FOR SELECT TO app_user
  USING (user_id = app.current_actor_user());
CREATE POLICY tenant_insert ON "app"."memberships" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));
CREATE POLICY tenant_update ON "app"."memberships" FOR UPDATE TO app_user
  USING (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()))
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));
CREATE POLICY tenant_delete ON "app"."memberships" FOR DELETE TO app_user
  USING (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));

-- invitations, projects, client_contacts: standard tenant read + writable-workspace writes. No DELETE:
-- these are revoked or soft-deleted, and purged by the retention job (SEC-20, P8).
CREATE POLICY tenant_select ON "app"."invitations" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace());
CREATE POLICY tenant_insert ON "app"."invitations" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));
CREATE POLICY tenant_update ON "app"."invitations" FOR UPDATE TO app_user
  USING (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()))
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));

CREATE POLICY tenant_select ON "app"."projects" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace());
-- New projects always start as Draft (FR-PRJ-01/05); later states only through validated transitions.
CREATE POLICY tenant_insert ON "app"."projects" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace() AND status = 'draft' AND (SELECT app.workspace_writable()));
CREATE POLICY tenant_update ON "app"."projects" FOR UPDATE TO app_user
  USING (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()))
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));

CREATE POLICY tenant_select ON "app"."client_contacts" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace());
CREATE POLICY tenant_insert ON "app"."client_contacts" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));
CREATE POLICY tenant_update ON "app"."client_contacts" FOR UPDATE TO app_user
  USING (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()))
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));

-- domains: members may only create platform subdomains in P1; custom/portal domains arrive with P7A.
CREATE POLICY tenant_select ON "app"."domains" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace());
CREATE POLICY tenant_insert ON "app"."domains" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace() AND type = 'subdomain' AND (SELECT app.workspace_writable()));
CREATE POLICY tenant_update ON "app"."domains" FOR UPDATE TO app_user
  USING (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()))
  WITH CHECK (workspace_id = app.current_workspace() AND (SELECT app.workspace_writable()));

-- audit_logs: read and append within the workspace. Not gated on writable: denied actions in a suspended
-- workspace must still be recorded. Platform rows (workspace_id NULL) are invisible to app_user.
CREATE POLICY tenant_select ON "app"."audit_logs" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace());
CREATE POLICY tenant_insert ON "app"."audit_logs" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace());

-- notifications: anyone in the workspace context may notify a member (the composite FK guarantees the
-- recipient is one); only the recipient can read, mark read or delete. Because INSERT ... RETURNING must
-- also pass the SELECT policy, notifying someone else uses createMany (no RETURNING).
CREATE POLICY tenant_insert ON "app"."notifications" FOR INSERT TO app_user
  WITH CHECK (workspace_id = app.current_workspace());
CREATE POLICY recipient_select ON "app"."notifications" FOR SELECT TO app_user
  USING (workspace_id = app.current_workspace() AND user_id = app.current_actor_user());
CREATE POLICY recipient_update ON "app"."notifications" FOR UPDATE TO app_user
  USING (workspace_id = app.current_workspace() AND user_id = app.current_actor_user())
  WITH CHECK (workspace_id = app.current_workspace() AND user_id = app.current_actor_user());
CREATE POLICY recipient_delete ON "app"."notifications" FOR DELETE TO app_user
  USING (workspace_id = app.current_workspace() AND user_id = app.current_actor_user());

-- platform_admins: no app_user policy at all. svc_definer policies follow in section 6.

-- ---------------------------------------------------------------- 5. privileges (least privilege)
GRANT USAGE ON SCHEMA "identity" TO app_auth, svc_definer;
GRANT USAGE ON SCHEMA "app" TO app_user, app_auth, app_public, app_admin, svc_definer;

-- identity: Better Auth (app_auth) only. app_user, app_public and app_admin have no USAGE on the schema.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA "identity" TO app_auth;

-- app: column lists keep server-controlled columns (status, suspension, plan, ids, ownership) out of reach.
GRANT SELECT ON "app"."workspaces", "app"."memberships", "app"."invitations", "app"."projects",
  "app"."client_contacts", "app"."domains", "app"."audit_logs", "app"."notifications" TO app_user;
-- `status` is in the INSERT list because Prisma sends enum defaults explicitly; the INSERT policies pin it.
GRANT INSERT (id, name, slug, status, created_by, created_at, updated_at) ON "app"."workspaces" TO app_user;
GRANT UPDATE (name, deleted_at, scheduled_purge_at, updated_at) ON "app"."workspaces" TO app_user;
GRANT INSERT (id, workspace_id, user_id, role, created_by, created_at, updated_at) ON "app"."memberships" TO app_user;
GRANT UPDATE (role, updated_at) ON "app"."memberships" TO app_user;
GRANT DELETE ON "app"."memberships" TO app_user;
GRANT INSERT (id, workspace_id, email, role, token_hash, expires_at, invited_by, created_at, updated_at)
  ON "app"."invitations" TO app_user;
GRANT UPDATE (revoked_at, updated_at) ON "app"."invitations" TO app_user;
GRANT INSERT (id, workspace_id, name, category, city, status, template_id, template_version_id, client_contact_id,
  created_by, created_at, updated_at, status_changed_at) ON "app"."projects" TO app_user;
GRANT UPDATE (name, category, city, status, status_changed_at, template_id, template_version_id,
  client_contact_id, deleted_at, updated_at) ON "app"."projects" TO app_user;
GRANT INSERT (id, workspace_id, project_id, name, phone, email, whatsapp, created_by, created_at, updated_at)
  ON "app"."client_contacts" TO app_user;
GRANT UPDATE (name, phone, email, whatsapp, deleted_at, updated_at) ON "app"."client_contacts" TO app_user;
GRANT INSERT (id, workspace_id, project_id, hostname, type, status, activated_at, created_at, updated_at)
  ON "app"."domains" TO app_user;
GRANT UPDATE (deleted_at, updated_at) ON "app"."domains" TO app_user;
GRANT INSERT ON "app"."audit_logs" TO app_user;
GRANT INSERT (id, workspace_id, user_id, type, payload, created_at) ON "app"."notifications" TO app_user;
GRANT UPDATE (read_at) ON "app"."notifications" TO app_user;
GRANT DELETE ON "app"."notifications" TO app_user;

-- ---------------------------------------------------------------- 6. SECURITY DEFINER functions
-- Owned by svc_definer (NOLOGIN, NOBYPASSRLS, Spike B B-6). It is bound by FORCE RLS like everyone else, so each
-- capability below needs an explicit, reviewable policy. Every function pins `search_path = ''`.

-- Platform audit events (workspace_id NULL), e.g. sign-in or session revocation from Better Auth (app_auth).
CREATE FUNCTION app.record_platform_audit(
  p_actor_type app.audit_actor_type, p_actor_id uuid, p_action text, p_target_type text, p_target_id text,
  p_result app.audit_result, p_correlation_id text, p_metadata jsonb, p_ip inet, p_user_agent text
) RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_id uuid := app.uuid_generate_v7();
BEGIN
  IF p_actor_type NOT IN ('user', 'system', 'job') THEN
    RAISE EXCEPTION 'actor type % is not allowed for platform events', p_actor_type USING ERRCODE = '22023';
  END IF;
  INSERT INTO app.audit_logs (id, workspace_id, project_id, actor_type, actor_id, action, target_type, target_id,
                              result, correlation_id, metadata, ip, user_agent)
  VALUES (v_id, NULL, NULL, p_actor_type, p_actor_id, p_action, p_target_type, p_target_id,
          p_result, p_correlation_id, COALESCE(p_metadata, '{}'::jsonb), p_ip, p_user_agent);
  RETURN v_id;
END
$$;

-- Suspend / unsuspend a workspace (FR-WS-04, FR-ADM-02, SEC-17). The caller (app_admin) passes the admin's user
-- id after its own session + MFA checks; the database re-checks that the user is an active platform admin
-- with TOTP enrolled, requires a reason and writes the audit row in the same transaction. Returns false when
-- the workspace already had the requested status (idempotent: no change, no audit row).
CREATE FUNCTION app.admin_set_workspace_status(
  p_admin_user_id uuid, p_workspace_id uuid, p_status app.workspace_status, p_reason text, p_correlation_id text
) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_previous app.workspace_status;
BEGIN
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'a reason of 3 to 500 characters is required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM app.platform_admins a JOIN identity.users u ON u.id = a.user_id
     WHERE a.user_id = p_admin_user_id AND a.revoked_at IS NULL
       AND u.status = 'active' AND u.two_factor_enabled IS TRUE
  ) THEN
    RAISE EXCEPTION 'not an active platform admin with MFA' USING ERRCODE = '42501';
  END IF;

  SELECT w.status INTO v_previous FROM app.workspaces w WHERE w.id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_previous = p_status THEN
    RETURN false;
  END IF;

  UPDATE app.workspaces
     SET status = p_status,
         suspended_at = CASE WHEN p_status = 'suspended' THEN pg_catalog.now() END,
         suspended_reason = CASE WHEN p_status = 'suspended' THEN p_reason END,
         updated_at = pg_catalog.now()
   WHERE id = p_workspace_id;

  INSERT INTO app.audit_logs (id, workspace_id, actor_type, actor_id, action, target_type, target_id, result,
                              correlation_id, metadata)
  VALUES (app.uuid_generate_v7(), p_workspace_id, 'platform_admin', p_admin_user_id,
          CASE WHEN p_status = 'suspended' THEN 'admin.workspace.suspended' ELSE 'admin.workspace.unsuspended' END,
          'workspace', p_workspace_id::text, 'success', p_correlation_id,
          pg_catalog.jsonb_build_object('reason', p_reason, 'previous_status', v_previous));
  RETURN true;
END
$$;

-- Operator runbook only (connect as migrator through DIRECT_URL): grant or revoke the PlatformAdmin role.
-- No application role can execute these. Both write a platform audit row (actor_type 'system').
CREATE FUNCTION app.operator_grant_platform_admin(p_user_id uuid, p_reason text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  INSERT INTO app.platform_admins AS a (user_id, reason, granted_at, revoked_at)
  VALUES (p_user_id, p_reason, pg_catalog.now(), NULL)
  ON CONFLICT (user_id) DO UPDATE SET reason = EXCLUDED.reason, granted_at = EXCLUDED.granted_at, revoked_at = NULL;
  INSERT INTO app.audit_logs (id, workspace_id, actor_type, action, target_type, target_id, result, metadata)
  VALUES (app.uuid_generate_v7(), NULL, 'system', 'admin.platform_admin.granted', 'user', p_user_id::text,
          'success', pg_catalog.jsonb_build_object('reason', p_reason));
END
$$;

CREATE FUNCTION app.operator_revoke_platform_admin(p_user_id uuid, p_reason text) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  UPDATE app.platform_admins SET revoked_at = pg_catalog.now() WHERE user_id = p_user_id AND revoked_at IS NULL;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  INSERT INTO app.audit_logs (id, workspace_id, actor_type, action, target_type, target_id, result, metadata)
  VALUES (app.uuid_generate_v7(), NULL, 'system', 'admin.platform_admin.revoked', 'user', p_user_id::text,
          'success', pg_catalog.jsonb_build_object('reason', p_reason));
  RETURN true;
END
$$;

-- What svc_definer may touch, and nothing more.
GRANT SELECT (id, status, deleted_at) ON "app"."workspaces" TO svc_definer;
GRANT UPDATE (status, suspended_at, suspended_reason, updated_at) ON "app"."workspaces" TO svc_definer;
GRANT SELECT (user_id, reason, granted_at, revoked_at) ON "app"."platform_admins" TO svc_definer;
GRANT INSERT (user_id, reason, granted_at, revoked_at), UPDATE (reason, granted_at, revoked_at)
  ON "app"."platform_admins" TO svc_definer;
CREATE POLICY definer_insert ON "app"."platform_admins" FOR INSERT TO svc_definer WITH CHECK (true);
CREATE POLICY definer_update ON "app"."platform_admins" FOR UPDATE TO svc_definer USING (true) WITH CHECK (true);
GRANT SELECT (id, status, two_factor_enabled) ON "identity"."users" TO svc_definer;
GRANT INSERT ON "app"."audit_logs" TO svc_definer;
CREATE POLICY definer_select ON "app"."workspaces" FOR SELECT TO svc_definer USING (true);
CREATE POLICY definer_update ON "app"."workspaces" FOR UPDATE TO svc_definer USING (true) WITH CHECK (true);
CREATE POLICY definer_select ON "app"."platform_admins" FOR SELECT TO svc_definer USING (true);
CREATE POLICY definer_insert ON "app"."audit_logs" FOR INSERT TO svc_definer WITH CHECK (true);

-- EXECUTE grants come BEFORE the ownership transfer: afterwards migrator is no longer the owner, and a
-- GRANT/REVOKE by a non-owner only raises a WARNING and changes nothing.
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA "app" FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.uuid_generate_v7(), app.current_workspace(), app.current_actor_user(),
  app.workspace_writable() TO app_user;
GRANT EXECUTE ON FUNCTION app.uuid_generate_v7(), app.current_workspace() TO svc_definer;
GRANT EXECUTE ON FUNCTION app.record_platform_audit(app.audit_actor_type, uuid, text, text, text,
  app.audit_result, text, jsonb, inet, text) TO app_auth;
GRANT EXECUTE ON FUNCTION app.admin_set_workspace_status(uuid, uuid, app.workspace_status, text, text) TO app_admin;

-- Ownership transfer needs CREATE on the schema for the new owner during the statement only (Spike B B-8).
GRANT CREATE ON SCHEMA "app" TO svc_definer;
ALTER FUNCTION app.workspace_writable() OWNER TO svc_definer;
ALTER FUNCTION app.record_platform_audit(app.audit_actor_type, uuid, text, text, text, app.audit_result, text,
  jsonb, inet, text) OWNER TO svc_definer;
ALTER FUNCTION app.admin_set_workspace_status(uuid, uuid, app.workspace_status, text, text) OWNER TO svc_definer;
ALTER FUNCTION app.operator_grant_platform_admin(uuid, text) OWNER TO svc_definer;
ALTER FUNCTION app.operator_revoke_platform_admin(uuid, text) OWNER TO svc_definer;
REVOKE CREATE ON SCHEMA "app" FROM svc_definer;
-- The ownership transfer rewrites ACL entries naming the old owner, so a grant to migrator itself must be
-- made by the new owner (migrator holds SET on svc_definer, Spike B B-7).
SET ROLE svc_definer;
GRANT EXECUTE ON FUNCTION app.operator_grant_platform_admin(uuid, text),
  app.operator_revoke_platform_admin(uuid, text) TO migrator;
RESET ROLE;

-- ---------------------------------------------------------------- 7. append-only audit trail (FR-AUD-01, Q8)
-- No role has UPDATE or DELETE on audit_logs, and this trigger also stops the owner. PII anonymisation for
-- erasure requests will be a reviewed SECURITY DEFINER function (P8), never an ad-hoc UPDATE.
CREATE FUNCTION app.audit_logs_reject_change() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only (% rejected)', TG_OP USING ERRCODE = '42501';
END
$$;
REVOKE ALL ON FUNCTION app.audit_logs_reject_change() FROM PUBLIC;
CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE ON "app"."audit_logs"
  FOR EACH ROW EXECUTE FUNCTION app.audit_logs_reject_change();
CREATE TRIGGER audit_logs_no_truncate BEFORE TRUNCATE ON "app"."audit_logs"
  FOR EACH STATEMENT EXECUTE FUNCTION app.audit_logs_reject_change();
